css:
.lsm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lsm-root,.lsm-root *,.lsm-root *::before,.lsm-root *::after{box-sizing:border-box}
.lsm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lsm-root img{display:block;border:0;max-width:none}
.lsm-root [hidden]{display:none!important}
.lsm-root .n30_371{grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;place-items:start;position:relative;flex-shrink:0}
.lsm-root .n30_325{grid-column:1;height:98px;margin-left:0;margin-top:0;position:relative;grid-row:1;width:124px}
.lsm-root .x94{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lsm-root .n30_359{grid-column:1;align-content:stretch;display:flex;flex-direction:column;height:23px;align-items:flex-start;justify-content:center;margin-left:2px;margin-top:2px;padding-bottom:5px;padding-left:5px;padding-right:12px;padding-top:4px;position:relative;border-bottom-right-radius:100px;border-top-right-radius:100px;grid-row:1;border-style:solid;border-color:var(--wa-point, #5468c0);border-width:1px;background-image:linear-gradient(to left,var(--wa-point, #011056),color-mix(in srgb, var(--wa-point, rgb(1 16 86)) 0%, transparent))}
.lsm-root .n30_357{align-content:stretch;display:flex;gap:6px;align-items:center;position:relative;flex-shrink:0}
.lsm-root .n30_346{height:11px;position:relative;flex-shrink:0;width:10px}
.lsm-root .x95{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lsm-root .n30_348{word-break:break-word;font-family:"NanumSquare","Pretendard",sans-serif;font-weight:700;line-height:14px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text, #fefeff);font-size:12px;white-space:nowrap;width:22px}
.lsm-root .n30_366{word-break:break-word;grid-column:1;align-content:stretch;display:flex;gap:4px;align-items:baseline;justify-content:center;line-height:normal;margin-left:28px;margin-top:43px;font-style:normal;position:relative;grid-row:1;color:var(--wa-text, #fff);white-space:nowrap}
.lsm-root .n30_364{font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;position:relative;flex-shrink:0;font-size:28px;width:53px;line-height:33px;white-space:nowrap}
.lsm-root .n30_365{font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;position:relative;flex-shrink:0;font-size:16px;width:11px;line-height:19px;white-space:nowrap}
.lsm-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lsm-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lsm-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lsm-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lsm-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lsm-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lsm-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.lsm-root[data-theme="light"] .n30_359{border-color:var(--wa-point, #7a88c2)}
